using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Web.Script.Serialization;
using System.Xml.Linq;
using Ingestion;
namespace Ingestion.Plugins {
    internal static class AdapterHelpers {
        internal static Encoding TextEncoding(InputFile f){return Encoding.GetEncoding(String.IsNullOrEmpty(f.encoding)||f.encoding=="utf-8-sig"?"utf-8":f.encoding,EncoderFallback.ExceptionFallback,DecoderFallback.ExceptionFallback);}
        internal static List<string[]> Delimited(string text,char delimiter){var rows=new List<string[]>();var row=new List<string>();var field=new StringBuilder();bool quoted=false,endedQuote=false;for(int i=0;i<text.Length;i++){char c=text[i];if(quoted){if(c=='"'){if(i+1<text.Length&&text[i+1]=='"'){field.Append('"');i++;}else{quoted=false;endedQuote=true;}}else field.Append(c);}else if(c=='"'){if(field.Length!=0||endedQuote)throw new InvalidDataException("INVALID_CSV_QUOTE");quoted=true;}else if(c==delimiter){row.Add(field.ToString());field.Clear();endedQuote=false;}else if(c=='\r'||c=='\n'){if(c=='\r'&&i+1<text.Length&&text[i+1]=='\n')i++;row.Add(field.ToString());if(row.Any(x=>x.Length>0))rows.Add(row.ToArray());row.Clear();field.Clear();endedQuote=false;}else{if(endedQuote)throw new InvalidDataException("CHAR_AFTER_QUOTE");field.Append(c);}}if(quoted)throw new InvalidDataException("TRUNCATED_QUOTED_FIELD");if(field.Length>0||row.Count>0||endedQuote){row.Add(field.ToString());if(row.Any(x=>x.Length>0))rows.Add(row.ToArray());}return rows;}
        internal static List<CanonicalRecord> Records(List<string[]> rows){if(rows.Count<2)throw new InvalidDataException("NO_TABLE_RECORDS");string[] headers=rows[0].Select(x=>x.Trim().TrimStart('\ufeff')).ToArray();if(headers.Distinct().Count()!=headers.Length)throw new InvalidDataException("DUPLICATE_HEADER");foreach(var required in Validator.Fields)if(!headers.Contains(required))throw new InvalidDataException("MISSING_HEADER:"+required);var records=new List<CanonicalRecord>();for(int i=1;i<rows.Count;i++){if(rows[i].Length!=headers.Length)throw new InvalidDataException("COLUMN_COUNT_MISMATCH:row="+(i+1));var d=new Dictionary<string,string>();for(int c=0;c<headers.Length;c++)d[headers[c]]=rows[i][c];records.Add(Utilities.FromRow(d));}return records;}
        internal static List<CanonicalRecord> Csv(ParseContext c){var declared=TextEncoding(c.Input);using(var bom=File.OpenRead(c.FullPath)){byte[] prefix=new byte[3];int n=bom.Read(prefix,0,3);int detected=n>=2&&prefix[0]==255&&prefix[1]==254?1200:n>=2&&prefix[0]==254&&prefix[1]==255?1201:n>=3&&prefix[0]==239&&prefix[1]==187&&prefix[2]==191?65001:0;if(detected!=0&&detected!=declared.CodePage)throw new InvalidDataException("ENCODING_DECLARATION_BOM_MISMATCH");}using(var r=new StreamReader(c.FullPath,declared,true)){string delimiter=String.IsNullOrEmpty(c.Input.delimiter)?",":c.Input.delimiter;if(delimiter.Length!=1)throw new InvalidDataException("DELIMITER_MUST_BE_ONE_CHARACTER");return Records(Delimited(r.ReadToEnd(),delimiter[0]));}}
        static int Column(string cell){int result=0;foreach(char c in cell){if(c<'A'||c>'Z')break;result=result*26+c-'A'+1;}return result-1;}
        internal static List<CanonicalRecord> Xlsx(ParseContext c){using(var z=ZipFile.OpenRead(c.FullPath)){XNamespace ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main";var shared=new List<string>();var ss=z.GetEntry("xl/sharedStrings.xml");if(ss!=null)using(var s=ss.Open())shared=XDocument.Load(s).Descendants(ns+"si").Select(si=>String.Concat(si.Descendants(ns+"t").Select(t=>t.Value))).ToList();XNamespace rel="http://schemas.openxmlformats.org/officeDocument/2006/relationships";string relationship;using(var s=z.GetEntry("xl/workbook.xml").Open())relationship=(string)XDocument.Load(s).Descendants(ns+"sheet").First().Attribute(rel+"id");string target;using(var s=z.GetEntry("xl/_rels/workbook.xml.rels").Open())target=(string)XDocument.Load(s).Root.Elements().First(e=>(string)e.Attribute("Id")==relationship).Attribute("Target");string entry=target.StartsWith("/")?target.TrimStart('/'):("xl/"+target);while(entry.Contains("/../")){int p=entry.IndexOf("/../"),prior=entry.LastIndexOf('/',p-1);entry=entry.Substring(0,prior)+entry.Substring(p+3);}var sheet=z.GetEntry(entry);if(sheet==null)throw new InvalidDataException("WORKSHEET_TARGET_MISSING:"+entry);var rows=new List<string[]>();using(var s=sheet.Open())foreach(var row in XDocument.Load(s).Descendants(ns+"sheetData").Elements(ns+"row")){var values=new SortedDictionary<int,string>();foreach(var cell in row.Elements(ns+"c")){int col=Column((string)cell.Attribute("r"));string type=(string)cell.Attribute("t"),v=(string)cell.Element(ns+"v")??"";if(type=="s")v=shared[Int32.Parse(v)];else if(type=="inlineStr")v=String.Concat(cell.Descendants(ns+"t").Select(t=>t.Value));else if(type=="e"||cell.Element(ns+"f")!=null)throw new InvalidDataException("ERROR_OR_FORMULA_CELL");values[col]=v;}if(values.Count>0){var a=Enumerable.Repeat("",values.Keys.Max()+1).ToArray();foreach(var v in values)a[v.Key]=v.Value;rows.Add(a);}}int width=rows.Count>0?rows[0].Length:0;for(int i=1;i<rows.Count;i++)if(rows[i].Length<width){var expanded=rows[i];Array.Resize(ref expanded,width);rows[i]=expanded;}return Records(rows);}}
        internal static List<CanonicalRecord> Docx(ParseContext c){using(var z=ZipFile.OpenRead(c.FullPath)){XNamespace ns="http://schemas.openxmlformats.org/wordprocessingml/2006/main";using(var s=z.GetEntry("word/document.xml").Open()){var table=XDocument.Load(s).Descendants(ns+"tbl").FirstOrDefault();if(table==null)throw new InvalidDataException("NO_DOCX_TABLE");var rows=table.Elements(ns+"tr").Select(row=>row.Elements(ns+"tc").Select(cell=>String.Concat(cell.Descendants(ns+"t").Select(t=>t.Value))).ToArray()).ToList();return Records(rows);}}}
        internal static List<CanonicalRecord> Sqlite(ParseContext c){using(var db=new NativeSqlite(c.FullPath,true)){var tables=db.Query("SELECT name FROM sqlite_master WHERE type='table' AND name='canonical_records';");if(tables.Count!=1)throw new InvalidDataException("MISSING_CANONICAL_RECORDS_TABLE");var rows=db.Query("SELECT * FROM canonical_records;");foreach(var key in Validator.Fields)if(rows.Count>0&&!rows[0].ContainsKey(key))throw new InvalidDataException("MISSING_HEADER:"+key);return rows.Select(Utilities.FromRow).ToList();}}
        static string Quote(string s){return "\""+s.Replace("\"","\\\"")+"\"";}
        internal static List<CanonicalRecord> Pdf(ParseContext c){var p=new ProcessStartInfo{FileName=c.PythonExecutable,Arguments=Quote(c.PdfBridgePath)+" "+Quote(c.FullPath),UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};using(var process=Process.Start(p)){string text=process.StandardOutput.ReadToEnd(),err=process.StandardError.ReadToEnd();process.WaitForExit();if(process.ExitCode!=0)throw new InvalidDataException("PDF_BRIDGE_FAILED:"+err);var rows=new JavaScriptSerializer{MaxJsonLength=int.MaxValue}.Deserialize<List<string[]>>(text);return Records(rows);}}
    }
}

